update public.company_positions
set sort_order = seed.sort_order
from (
  values
    ('00000000-0000-0000-0000-000000000101'::uuid, 10),
    ('00000000-0000-0000-0000-000000000102'::uuid, 20),
    ('00000000-0000-0000-0000-000000000103'::uuid, 30),
    ('00000000-0000-0000-0000-000000000105'::uuid, 40),
    ('00000000-0000-0000-0000-000000000107'::uuid, 50),
    ('00000000-0000-0000-0000-000000000108'::uuid, 60),
    ('00000000-0000-0000-0000-000000000104'::uuid, 70),
    ('00000000-0000-0000-0000-000000000110'::uuid, 72),
    ('00000000-0000-0000-0000-000000000111'::uuid, 74),
    ('00000000-0000-0000-0000-000000000109'::uuid, 80),
    ('00000000-0000-0000-0000-000000000106'::uuid, 90)
) as seed(id, sort_order)
where public.company_positions.id = seed.id;
